import json
from pathlib import Path
R=Path(__file__).resolve().parent
N=json.loads((R/'narration.json').read_text())
store='''<svg viewBox="0 0 128 128"><defs><linearGradient id="shopGrad" x2="0" y2="1"><stop stop-color="#ff7147"/><stop offset="1" stop-color="#f45b35"/></linearGradient></defs><path fill="url(#shopGrad)" d="M22 12h84a8 8 0 0 1 7 5l13 31H2l13-31a8 8 0 0 1 7-5ZM3 53h25v10a12.5 12.5 0 0 1-25 0Zm30 0h26v10a13 13 0 0 1-26 0Zm31 0h26v10a13 13 0 0 1-26 0Zm31 0h30v10a15 15 0 0 1-30 0ZM14 82h45v36H20a6 6 0 0 1-6-6Zm50 0h50v30a6 6 0 0 1-6 6H64Z"/><path d="M28 98h20m30 0h21" stroke="#fff9f0" stroke-width="4" stroke-linecap="round"/></svg>'''
fridge='''<svg viewBox="0 0 128 150"><defs><linearGradient id="fridgeGrad" x2="1" y2="1"><stop stop-color="#449797"/><stop offset="1" stop-color="#267b80"/></linearGradient></defs><rect x="10" y="6" width="108" height="138" rx="10" fill="url(#fridgeGrad)"/><path d="M64 8v104M34 117h60M34 129h60M52 52v22m24-22v22" fill="none" stroke="#f4fffa" stroke-width="4" stroke-linecap="round"/></svg>'''
