html='''<!doctype html><html><head><meta charset="utf-8"><title>Fabric ontology — image-first motion pilot</title><style>
@font-face{font-family:Source;src:url(assets/SourceSerif4.ttf);font-weight:200 900}*{box-sizing:border-box}html,body{margin:0;width:1920px;height:1080px;overflow:hidden}body{background:#fff;color:#172129}#stage{position:relative;width:1920px;height:1080px;background:radial-gradient(ellipse at 45% 50%,#fffdf9 0%,#fff 78%)}#grid{position:absolute;inset:0;background-image:linear-gradient(#ede8df85 1px,transparent 1px),linear-gradient(90deg,#ede8df85 1px,transparent 1px);background-size:88px 88px;opacity:.65}.serif{font-family:Source,Georgia,serif;font-weight:400;font-optical-sizing:auto}#eyebrow{position:absolute;left:116px;top:88px;font:500 19px Arial,sans-serif;letter-spacing:4.2px;color:#737a7d}h1{position:absolute;left:114px;top:118px;margin:0;font-size:86px;letter-spacing:-3.7px;line-height:1.2;white-space:nowrap}.entity{position:absolute;top:286px;width:470px;height:400px;transform-origin:center center}.surface{position:absolute;inset:0;border:1.4px solid #dfddd6;border-radius:30px;background:linear-gradient(145deg,#fff,#f8f7f4);box-shadow:0 16px 27px #85765e14,0 3px 8px #66594705}#store{left:298px}#unit{left:1156px}#store .surface{border-color:#ffbb95;background:radial-gradient(ellipse at 13% 8%,#fff9f1cf,transparent 70%),linear-gradient(145deg,#fff0e2,#ffccab)}.icon{position:absolute;left:167px;top:54px;width:136px;height:136px}.icon svg{width:100%;height:100%}#unit .icon{top:53px;height:145px}#store-label{position:absolute;top:203px;left:0;width:100%;text-align:center;font-size:51px;line-height:1.2}#unit-label{position:absolute;top:232px;left:12px;width:446px;text-align:center;font-size:46px;line-height:1.2;letter-spacing:-1.2px}.type{position:absolute;top:263px;left:0;width:100%;font:500 17px Arial;letter-spacing:3.7px;text-align:center;color:#687074}#unit .type{top:299px}#props{position:absolute;inset:0}#divider{position:absolute;left:40px;right:40px;top:296px;border-top:1px solid #d67e4d30}.chip{position:absolute;top:314px;height:58px;width:191px;border:1.4px solid #e7b89488;border-radius:9px;box-shadow:0 2px 4px #985b2410;background:#fff7ed66;text-align:center;font-size:28px;line-height:56px}#region{left:40px}#priority{left:239px}#relation{position:absolute;left:782px;top:402px;width:360px;height:146px}#relation-label{text-align:center;font-size:46px;line-height:56px}.edge{position:absolute;left:0;top:69px;width:360px;height:32px}#relation-kind{position:absolute;top:108px;width:360px;text-align:center;font:500 17px Arial;letter-spacing:3px;color:#6c7478}.source{position:absolute;top:827px;width:456px;height:122px}.source .surface{border-radius:22px;box-shadow:0 12px 24px #85765e12}.source .tableicon{position:absolute;left:34px;top:30px;width:62px;height:62px;color:#636d70}.source .name{position:absolute;left:135px;top:20px;font-size:34px;white-space:nowrap;letter-spacing:-.5px}.source .key{position:absolute;left:135px;top:66px;font-size:27px;color:#778084}#store-source{left:307px}#unit-source{left:1158px;width:470px}#unit-source .name{left:124px;font-size:30px;letter-spacing:-.8px}#unit-source .key{left:124px}.binding{position:absolute;top:696px;height:131px;width:235px}#store-binding{left:528px}#unit-binding{left:1386px}.binding svg{position:absolute;left:0;top:0;width:30px;height:131px}.binding span{position:absolute;left:42px;top:60px;font-size:27px;color:#6b757a;white-space:nowrap}#footnote{position:absolute;left:80px;right:80px;top:996px;text-align:center;font-size:24px;color:#7c8386}#phase{position:absolute;right:115px;top:92px;font:500 16px Arial;letter-spacing:2px;color:#8b9293}body.preview #transport{display:block}#transport{display:none;position:fixed;bottom:10px;left:10px;z-index:99;background:white;border:1px solid #ddd;padding:8px;font:14px Arial}button{cursor:pointer}
</style></head><body><main id="stage"><div id="grid"></div><div id="eyebrow">MICROSOFT FABRIC · ONTOLOGY PREVIEW</div><h1 class="serif">Business meaning, connected to data</h1><div id="phase"></div>
<div id="store" class="entity"><div class="surface"></div><div class="icon">STORE_SVG</div><div id="store-label" class="serif">Store</div><div class="type">ENTITY TYPE</div><div id="props"><div id="divider"></div><div id="region" class="chip serif">Region</div><div id="priority" class="chip serif">Priority</div></div></div>
<div id="unit" class="entity"><div class="surface"></div><div class="icon">FRIDGE_SVG</div><div id="unit-label" class="serif">Refrigeration Unit</div><div class="type">ENTITY TYPE</div></div>
<div id="relation"><div id="relation-label" class="serif">operates</div><svg class="edge" viewBox="0 0 360 32"><path id="rel-line" d="M0 16H337" fill="none" stroke="#525e63" stroke-width="5"/><path id="rel-head" d="M337 5L358 16L337 27Z" fill="#525e63"/></svg><div id="relation-kind">RELATIONSHIP</div></div>
<div id="store-source" class="source"><div class="surface"></div><div class="tableicon">TABLE_SVG</div><div class="name serif">dimlocations</div><div class="key serif">LocationId</div></div>
<div id="unit-source" class="source"><div class="surface"></div><div class="tableicon">TABLE_SVG</div><div class="name serif">dim_refrigeration_units</div><div class="key serif">StoreId</div></div>
<div id="store-binding" class="binding"><svg viewBox="0 0 30 131"><path class="binding-line" d="M15 131V18" stroke="#626d72" stroke-width="2.5" stroke-dasharray="7 6"/><path class="binding-head" d="M7 18L15 3L23 18Z" fill="#626d72"/></svg><span class="serif">data binding</span></div>
<div id="unit-binding" class="binding"><svg viewBox="0 0 30 131"><path class="binding-line" d="M15 131V18" stroke="#626d72" stroke-width="2.5" stroke-dasharray="7 6"/><path class="binding-head" d="M7 18L15 3L23 18Z" fill="#626d72"/></svg><span class="serif">data binding</span></div>
<div id="footnote" class="serif">Illustrative model · Source data stays in its source</div></main><div id="transport"><button id="play">Play with narration</button> <span id="clock"></span></div><audio id="audio" src="ontology-narration.m4a" preload="auto"></audio><script>
const narration=NARRATION_JSON;const duration=narration.duration;
const seg=narration.segments.map(s=>s.start);
const clamp=x=>Math.max(0,Math.min(1,x));const ease=x=>{x=clamp(x);return x*x*(3-2*x)};
const smooth=(t,a,d)=>ease((t-a)/d);const el=id=>document.getElementById(id);
function appear(id,t,a,d=.65,dy=16){const v=smooth(t,a,d);el(id).style.opacity=v;el(id).style.transform=`translateY(${dy*(1-v)}px)`;return v}
window.renderAt=function(t){
 const intro=smooth(t,.15,.65);let scale=1;if(t<.8)scale=.91+.105*intro;else if(t<1.15)scale=1.015-.015*smooth(t,.8,.35);el('store').style.opacity=intro;el('store').style.transform=`scale(${scale})`;
 appear('props',t,seg[1]+.2,.65,0);appear('region',t,seg[1]+.2,.6,7);appear('priority',t,seg[1]+.8,.6,7);
 appear('unit',t,seg[2]+1.1,.7,12);
 const rel=smooth(t,seg[2]+1.9,.75);el('relation').style.opacity=smooth(t,seg[2]+1.7,.5);el('rel-line').style.strokeDasharray=337;el('rel-line').style.strokeDashoffset=337*(1-rel);el('rel-head').style.opacity=smooth(t,seg[2]+2.45,.25);
 appear('store-source',t,seg[3]+.25,.65,14);appear('unit-source',t,seg[3]+.6,.65,14);
 for(const [id,at] of [['store-binding',seg[3]+1.05],['unit-binding',seg[3]+1.4]]){const v=smooth(t,at,.8);el(id).style.opacity=v;el(id).style.clipPath=`inset(${(1-v)*100}% 0 0 0)`}
 const focus=smooth(t,seg[3]+5,.7);el('store-source').style.filter=`drop-shadow(0 0 ${focus*9}px #b8a37a12)`;el('unit-source').style.filter=`drop-shadow(0 0 ${focus*9}px #b8a37a12)`;
 el('phase').textContent=t<seg[1]?'01 / ENTITY':t<seg[2]?'02 / PROPERTIES':t<seg[3]?'03 / RELATIONSHIP':'04 / DATA BINDING';
 return {time:t,duration,relationship:rel,props:smooth(t,seg[1]+.2,.65)};
};window.renderAt(0);
if(new URLSearchParams(location.search).has('play')){document.body.classList.add('preview');const audio=el('audio');el('play').onclick=()=>{if(audio.paused){if(audio.currentTime>=duration-.1)audio.currentTime=0;audio.play()}else audio.pause()};function tick(){renderAt(audio.currentTime);el('clock').textContent=audio.currentTime.toFixed(1)+' / '+duration.toFixed(1);requestAnimationFrame(tick)}tick()}
</script></body></html>'''
html=html.replace('STORE_SVG',store).replace('FRIDGE_SVG',fridge).replace('TABLE_SVG',table).replace('NARRATION_JSON',json.dumps(N))
theme=json.loads((R.parent/'content/visual-language/fabric-brand/theme.json').read_text())
for old,new in theme['reference_color_substitutions'].items():
 html=html.replace(old,new)
(R/'scene.html').write_text(html)
print('Built',R/'scene.html')
